mapper.select:
SELECT s.semester AS semester, s.create_time AS examTime, c.id AS courseId, c.course_name AS courseName, s.score AS score FROM score s INNER JOIN course c ON s.course_id = c.id WHERE s.student_id = #{studentId}
AND s.course_id = #{courseId}
AND c.course_name = #{courseName}
ORDER BY s.create_time ASC
